proc makeArray(size: int, type t): [] t {
  var D = {0..#size};
  var a: [D] t;
  return a;
}

record Tensor {
  var shape: [] int;
  var data: [] real;

  proc init(in shp: [] int) {
    this.shape = shp;
    var size = 1;
    for s in shp do size *= s;
    this.data = makeArray(size, real);
  }

  proc numElements(): int {
    var size = 1;
    for s in shape do size *= s;
    return size;
  }

  proc fill(value: real) {
    forall i in data do i = value;
  }

  proc ref add(other: Tensor) {
    if shape != other.shape then halt("Shape mismatch");
    forall (i, j) in zip(data, other.data) do i += j;
  }

  proc norm2(): real {
    var norm = + reduce (data ** 2);
    return sqrt(norm);
  }

  proc divScalar(val: real) {
    forall i in data do i /= val;
  }
}

proc matmul(A: Tensor, B: Tensor): Tensor {
  if A.shape[1] != B.shape[0] then halt("Matmul shape mismatch");
  var sh: list(int);
  sh.append(A.shape[0]);
  sh.append(B.shape[1]);
  var shp = sh.toArray();
  var C = new Tensor(shp);
  C.fill(0.0);
  const Ash1 = A.shape[1];
  const Bsh0 = B.shape[0];
  const Bsh1 = B.shape[1];
  const Csh1 = C.shape[1];
  forall i in 0..#A.shape[0] {
    forall j in 0..#B.shape[1] {
      var sum: real = 0.0;
      for k in 0..#Ash1 {
        sum += A.data[i * Ash1 + k] * B.data[k * Bsh1 + j];
      }
      C.data[i * Csh1 + j] = sum;
    }
  }
  return C;
}

