  var kanGrid: int = 5;
  var tgnNodeFeat: int;
  var tgnTimeDim: int;
  var vocabSize: int = 50257;
  var quantumQubits: int = 88;

  proc init() {
    this.dim = 18432;
    this.ssmDState = this.dim;
    this.tgnNodeFeat = this.dim;
    this.tgnTimeDim = this.dim;
  }
}

class CelestialZO {
  proc init() {}
  proc deinit() {}
}

class FMRNModel {
  var config: FMRNConfig;
  var layers: [] owned FMRNLayer;
  var weights: owned Tensor;
  var ssmStates: [] owned Tensor;
  var tgnMemory: [] owned Tensor;
  var quantum: owned QuantumSimulator?;
  var optimizer: owned CelestialZO;

  proc init() {
    this.config = new FMRNConfig();
    this.layers = makeArray(this.config.layers, owned FMRNLayer);
    for i in 0..#this.config.layers {
      this.layers[i] = new owned FMRNLayer(this.config.dim, this.config.ssmDState, this.config.kanGrid, this.config.tgnNodeFeat, this.config.tgnTimeDim);
    }
    var sh: list(int);
    sh.append(this.config.vocabSize);
    sh.append(this.config.dim);
    var shp = sh.toArray();
    this.weights = new owned Tensor(shp);
    fillRandom(this.weights.data);
    this.ssmStates = makeArray(this.config.layers, owned Tensor);
    for i in 0..#this.config.layers {
      var ssh: list(int);
      ssh.append(this.config.ssmDState);
      var sshape = ssh.toArray();
      this.ssmStates[i] = new owned Tensor(sshape);
      this.ssmStates[i].fill(0.0);
    }
    this.tgnMemory = makeArray(this.config.ssmDState, owned Tensor);
    for i in 0..#this.config.ssmDState {
      var tsh: list(int);
      tsh.append(this.config.tgnNodeFeat);
      var tshape = tsh.toArray();
      this.tgnMemory[i] = new owned Tensor(tshape);
      this.tgnMemory[i].fill(0.0);
    }
    if this.config.quantumQubits > 0 then this.quantum = new owned QuantumSimulator();
    this.optimizer = new owned CelestialZO();
  }

  proc forward(input: [] real): owned Tensor {
    var embeds = this.embed(input);
    for l in 0..#this.config.layers {
      var kanOut = this.kanLayer(embeds, l);
      var ssmOut = this.ssmStep(kanOut, l);
      var tgnOut = this.tgnUpdate(ssmOut, l);
      embeds = tgnOut;
    }
    var lsh: list(int);
    lsh.append(input.size);
    lsh.append(this.config.vocabSize);
    var lshape = lsh.toArray();
    var logits = new owned Tensor(lshape);
    logits = matmul(embeds, this.weights);
    return logits;
  }

  proc embed(input: [] real): Tensor {
    var esh: list(int);
    esh.append(input.size);
    esh.append(this.config.dim);
    var eshape = esh.toArray();
    var embedTensor = new Tensor(eshape);
    embedTensor.fill(0.0);
    forall i in 0..#input.size {
      const tok = input[i]: int;
      if tok >= 0 && tok < this.config.vocabSize {
        const rowStart = i * this.config.dim;
        forall j in 0..#this.config.dim with (ref embedTensor) {
          embedTensor.data[rowStart + j] = this.weights.data[j + tok * this.config.dim];
        }
      }
    }
    return embedTensor;
  }

  proc kanLayer(input: Tensor, layerIdx: int): Tensor {
    var output = new Tensor(input.shape);
    output.fill(0.0);
    const coeffs = this.layers[layerIdx].kanCoeffs;
    const insh1 = input.shape[1];
    const grid = coeffs.size;
    const coeffDim = coeffs[0].size;
    forall i in 0..#input.shape[0] {
      forall j in 0..#input.shape[1] {
        const idx = i * insh1 + j;
        const coeff = coeffs[j % grid][j % coeffDim];
        output.data[idx] = coeff * input.data[idx];
      }
    }
    return output;
  }

  proc ssmStep(input: Tensor, layerIdx: int): Tensor {
    var osh: list(int);
    osh.append(input.shape[0]);
    osh.append(this.config.ssmDState);
    var oshape = osh.toArray();
    var output = new Tensor(oshape);
    output.fill(0.0);
    const layer = this.layers[layerIdx];
    const state = this.ssmStates[layerIdx];
    const insh1 = input.shape[1];
    const outsh1 = output.shape[1];
    forall i in 0..#input.shape[0] {
      forall j in 0..#this.config.ssmDState {
        const u = input.data[i * insh1 + j % insh1];
        const val = layer.ssmA[j] * state.data[j] + layer.ssmB[j] * u;
        state.data[j] = val;
        output.data[i * outsh1 + j] = layer.ssmC[j] * val;
      }
    }
    return output;
  }

  proc tgnUpdate(input: Tensor, layerIdx: int): Tensor {
    var osh: list(int);
    osh.append(input.shape[0]);
    osh.append(this.config.tgnNodeFeat);
    var oshape = osh.toArray();
    var output = new Tensor(oshape);
    output.fill(0.0);
    const layer = this.layers[layerIdx];
    const insh1 = input.shape[1];
    const outsh1 = output.shape[1];
    const timeD = layer.tgnWeights[0].size;
    forall i in 0..#input.shape[0] {
      forall j in 0..#this.config.tgnNodeFeat {
        var sum: real = 0.0;
        for k in 0..#insh1 {
          sum += input.data[i * insh1 + k] * layer.tgnWeights[j][k % timeD];
        }
        output.data[i * outsh1 + j] = sum;
      }
    }
    return output;
  }
}

